class AsyncRankings(AsyncResource):
    """Places you've ranked and the 0 to 10 scores Beli gave them."""

    async def list(
        self, category: str = "RES", *, user: str | None = None
    ) -> builtins.list[Ranking]:
        """Rankings in one category, best first."""
        items = await self._send(ep.rankings(category, user))
        return sorted(items, key=lambda r: r.score if r.score is not None else -1, reverse=True)

    async def all(
        self, categories: builtins.list[str] | None = None, *, user: str | None = None
    ) -> builtins.list[Ranking]:
        """Rankings across every category on the account (or the ones given)."""
        if categories is None:
            categories = [c.code for c in await self._send(ep.categories())] or ["RES"]
        out: builtins.list[Ranking] = []
        for code in categories:
            out.extend(await self.list(code, user=user))
        return out

    async def visit_dates(self, business_id: int) -> builtins.list[str]:
        """ISO dates you logged visits to a place, newest first."""
        return await self._send(ep.visit_dates(business_id))

    async def count(self, *, user: str | None = None) -> int:
        return await self._send(ep.rank_count(user))

    async def count_this_year(self, year: int | None = None, *, user: str | None = None) -> int:
        return await self._send(ep.ranked_this_year(user, year))

    async def delete(self, ranking_id: int) -> Any:
        """Remove a ranking (Beli soft-deletes it). This writes to your account."""
        return await self._send(ep.delete_ranking(ranking_id))


