class AsyncNotes(AsyncResource):
    """Written reviews attached to rankings."""

    async def list(self, *, user: str | None = None) -> builtins.list[Note]:
        return await self._send(ep.notes(user, None))

    async def get(self, business_id: int, *, user: str | None = None) -> str | None:
        notes = await self._send(ep.notes(user, business_id))
        matching = [n for n in notes if n.business == business_id]
        return matching[-1].value if matching else None

    async def set(self, business_id: int, text: str) -> Any:
        """Write or replace your note on a place. This writes to your account."""
        return await self._send(ep.set_note(business_id, text))


